def _mini_graph(repo_root: Path, rel: str = "svc.py") -> dict:
    abs_path = (repo_root / rel).resolve()
    rp = abs_path.relative_to(repo_root.resolve()).as_posix()
    return {
        "nodes": [
            {
                "id": "file_node",
                "label": rel,
                "file_type": "code",
                "source_file": str(abs_path),
                "source_location": "L1",
            },
            {
                "id": "fn_node",
                "label": "tick()",
                "file_type": "code",
                "source_file": str(abs_path),
                "source_location": "L5",
            },
        ],
        "edges": [
            {
                "source": "file_node",
                "target": "fn_node",
                "relation": "contains",
                "confidence": "EXTRACTED",
                "source_file": rp,
            },
        ],
    }

